<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue';
import {NAlert,NButton,NDrawer,NDrawerContent,NInput,NPopconfirm,NSelect,NSlider,NSwitch,NTabs,NTabPane} from 'naive-ui';
import {Check,Download,Flower2,Leaf,Monitor,Plus,Settings2,Sparkles,Trash2,Upload} from 'lucide-vue-next';
import type {ControlStore} from '../control-types.ts';
import {EXPRESSION_NAMES,EXPRESSIONS} from '../../companion/expressions.ts';
import PetActor from '../../pets/PetActor.vue';
import {createPetClient} from '../../pets/client.ts';
import {definitionOf,type PetTheme,type PetInstance} from '../../pets/model.ts';
import {petImage} from '../../pets/render.ts';
const props=defineProps<{store:ControlStore;settingsRequest?:{id:string}|null}>();
const emit=defineEmits<{settingsOpened:[]}>();
const client=createPetClient(),{catalog,ready,busy,error}=client;
const category=ref<'builtin'|'custom'>('builtin'),selectedTheme=ref('flower-whispers'),hover=ref(''),editing=ref<string|null>(null),file=ref<HTMLInputElement>();
const layer=ref<PetInstance['layer']>('topmost'),name=ref(''),draftSize=ref(210);
const themes=computed(()=>catalog.value.themes.filter(t=>t.source===category.value));
const theme=computed(()=>themes.value.find(t=>t.id===selectedTheme.value)||themes.value[0]);
const instances=computed(()=>catalog.value.layout.instances);
const current=computed(()=>instances.value.find(p=>p.id===editing.value));
const currentDefinition=computed(()=>current.value?definitionOf(catalog.value.themes,current.value):undefined);
const plants=computed(()=>catalog.value.themes.flatMap(t=>t.pets.map(p=>({label:`${t.name} · ${p.name}`,value:`${t.id}/${p.id}`}))));
function changePlant(value:string){const [themeId,petId]=value.split('/');update({themeId,petId});}
const expressions=EXPRESSION_NAMES.map(value=>({label:EXPRESSIONS[value].label,value}));
const layers=[{label:'悬浮陪伴 · 始终置顶',value:'topmost'},{label:'贴在桌面 · 不遮挡窗口',value:'desktop'}];
const themeIcon=(id:string)=>id==='flower-whispers'?Flower2:Leaf;
async function act(action:()=>Promise<unknown>,success?:string){try{await action();if(success)props.store.notify(success);}catch(e){props.store.notify(e,'error');}}
async function add(petId:string){if(!theme.value)return;await act(async()=>{await client.add(theme.value!.id,petId,layer.value);if(!props.store.settings.companionEnabled)await props.store.setCompanion(true);},'已添加到桌面，可拖动位置，右键管理');}
function create(base?:PetTheme){void props.store.startCreation('pet').then(()=>{if(base)props.store.creationDraft=`请以宠物主题「${base.name}」（${base.id}）为参考，创作我的自定义植物主题。先读取 pet_read_format 和现有主题，只更换顶部植物，保留小伴原来的花盆、材质和表情，按我的要求调整：`;});}
let sizeTimer:ReturnType<typeof setTimeout>|undefined,pendingSize:{id:string;size:number}|undefined;
function flushSize(){clearTimeout(sizeTimer);const pending=pendingSize;pendingSize=undefined;if(pending)void act(()=>client.update(pending.id,{size:pending.size}));}
function resizePet(size:number){draftSize.value=size;if(!current.value)return;pendingSize={id:current.value.id,size};clearTimeout(sizeTimer);sizeTimer=setTimeout(flushSize,300);}
function update(patch:Partial<PetInstance>){if(current.value)void act(()=>client.update(current.value!.id,patch));}
watch([()=>props.settingsRequest,ready],([request,loaded])=>{if(request&&loaded){editing.value=request.id;emit('settingsOpened');}},{immediate:true});
watch(()=>current.value?.id,()=>{flushSize();name.value=current.value?.name||'';});
watch(()=>current.value?.size,value=>{draftSize.value=value??210;});
async function imported(e:Event){const input=e.target as HTMLInputElement;const chosen=input.files?.[0];if(!chosen)return;await act(async()=>{if(chosen.size>512*1024)throw Error('宠物主题不能超过 512 KiB');const value=JSON.parse(await chosen.text());await client.saveTheme(value);category.value='custom';selectedTheme.value=value.id;},'主题已导入');input.value='';}
function manage(e:Event){const id=(e as CustomEvent<{id:string}>).detail?.id;void client.load().then(()=>{editing.value=id||null;});}
onMounted(()=>{void client.load();window.addEventListener('pets-manage',manage);});
onBeforeUnmount(()=>{flushSize();client.dispose();window.removeEventListener('pets-manage',manage);});
</script>
<template>
<section class="ui-page pet-library" data-testid="companion-page">
 <header class="pet-library-header"><div><span class="pet-eyebrow">桌面宠物</span><h1>熟悉的小伴，长出新心情。</h1><p>还是熟悉的花盆和表情，换上你喜欢的植物，陪着你。</p></div><div class="pet-header-actions"><NButton round :disabled="!ready||busy" @click="file?.click()"><template #icon><Upload :size="15"/></template>导入主题</NButton><NButton round type="primary" data-testid="pet-create" @click="create()"><template #icon><Sparkles :size="16"/></template>AI 创作植物</NButton></div><input ref="file" type="file" hidden accept=".json,application/json" @change="imported"/></header>
 <NAlert v-if="error" type="error" :show-icon="false">{{ error }}<NButton text @click="client.load()">重新载入</NButton></NAlert>
 <NTabs v-model:value="category" type="line" class="pet-library-tabs"><NTabPane name="builtin"><template #tab>官方主题</template></NTabPane><NTabPane name="custom"><template #tab>自定义主题</template></NTabPane></NTabs>
 <div v-if="themes.length" class="pet-theme-grid">
  <button v-for="t in themes" :key="t.id" class="pet-theme-card" :class="{selected:theme?.id===t.id}" :style="{'--theme-color':t.color}" :data-testid="`pet-theme-${t.id}`" :aria-pressed="theme?.id===t.id" @click="selectedTheme=t.id"><div class="theme-card-copy"><component :is="themeIcon(t.id)" :size="19"/><strong>{{ t.name }}</strong><small>{{ t.pets.length }} 位小伙伴</small></div><div class="theme-card-art"><img v-for="p in t.pets.slice(0,3)" :key="p.id" :src="petImage(p)" alt=""/></div><p>{{ t.description }}</p><Check v-if="theme?.id===t.id" class="theme-selected" :size="16"/></button>
 </div>
 <div v-else-if="ready" class="pet-empty surface" data-testid="pet-custom-empty"><Sparkles :size="28"/><h2>你想象中的小伙伴，在这里诞生。</h2><p>保留小伴原来的花盆与表情，让 AI 创作你喜欢的花草。</p><NButton type="primary" round @click="create()">开始创作</NButton></div>
 <section v-if="theme" class="pet-theme-detail">
  <header class="pet-section-heading"><div><h2>{{ theme.name }}<span>{{ theme.pets.length }} 款宠物</span></h2><p>{{ theme.description }}</p></div><div class="theme-actions"><button @click="create(theme)"><Sparkles :size="14"/>基于此主题创作</button><button :disabled="busy" @click="act(()=>client.exportTheme(theme!.id))" title="导出主题"><Download :size="16"/></button><NPopconfirm v-if="theme.source==='custom'" @positive-click="act(()=>client.deleteTheme(theme!.id))"><template #trigger><button :disabled="busy" title="删除主题"><Trash2 :size="16"/></button></template>删除这个自定义主题？已添加的宠物需先移除。</NPopconfirm></div></header>
  <div class="pet-add-preference"><Monitor :size="14"/><span>新宠物放在</span><NSelect v-model:value="layer" size="small" :options="layers" style="width:210px"/></div>
  <div class="pet-cards"><article v-for="p in theme.pets" :key="p.id" class="pet-card surface" :data-testid="`pet-card-${p.id}`" @pointerenter="hover=p.id" @pointerleave="hover=''">
   <div class="pet-card-stage" :style="{'--theme-color':theme.color}"><PetActor v-if="hover===p.id" :definition="p" :size="176" :paused="store.settings.paused"/><img v-else :src="petImage(p)" :alt="p.name" width="176" height="176"/><span class="pet-stage-hint">戳一戳，会回应你</span></div><div class="pet-card-copy"><h3>{{ p.name }}</h3><p>{{ p.description }}</p></div><NButton round block :disabled="!ready||busy" :data-testid="`pet-add-${p.id}`" @click="add(p.id)"><template #icon><Plus :size="15"/></template>添加到桌面</NButton>
  </article></div>
 </section>
 <section class="desktop-pets surface" data-testid="desktop-pets"><header class="pet-section-heading"><div><h2>桌面上的伙伴<span>{{ instances.length }} 只</span></h2><p>每一只都有独立的心情和位置。同一款，也可以多养几只。</p></div><label class="all-pets-switch"><span>全部显示</span><NSwitch :value="store.settings.companionEnabled" @update:value="value=>act(()=>store.setCompanion(value))"/></label></header>
  <div v-if="!instances.length" class="desktop-pets-empty">还没有小伙伴，挑一只喜欢的添加到桌面吧。</div>
  <div v-else class="desktop-pet-list"><div v-for="p in instances" :key="p.id" class="desktop-pet-row" :data-testid="`pet-instance-${p.id}`"><img v-if="definitionOf(catalog.themes,p)" :src="petImage(definitionOf(catalog.themes,p)!)" alt="" width="58" height="58"/><div class="desktop-pet-name"><strong>{{ p.name }}</strong><small>{{ catalog.themes.find(t=>t.id===p.themeId)?.name||'作品暂不可用' }} · {{ p.size }}px · {{ p.layer==='desktop'?'贴在桌面':'悬浮陪伴' }}</small></div><span class="pet-mood">{{ EXPRESSIONS[p.expression].label }}</span><NSwitch :value="p.enabled" size="small" :disabled="busy" :aria-label="`显示${p.name}`" @update:value="enabled=>act(()=>client.update(p.id,{enabled}))"/><button class="pet-manage" :aria-label="`管理${p.name}`" :data-testid="`pet-manage-${p.id}`" @click="editing=p.id"><Settings2 :size="16"/></button></div></div>
 </section>
 <NDrawer :show="!!current" :width="390" placement="right" @update:show="value=>{if(!value)editing=null}"><NDrawerContent v-if="current" :title="current.name" closable><div class="pet-editor"><div class="pet-editor-stage"><PetActor v-if="currentDefinition" :definition="currentDefinition" :size="210" :expression="current.expression" :links="current.links" :paused="store.settings.paused"/></div><label>顶部植物<NSelect :value="`${current.themeId}/${current.petId}`" :options="plants" filterable data-testid="pet-change-plant" @update:value="changePlant"/></label><label>名字<NInput v-model:value="name" :maxlength="40" @blur="name.trim()&&update({name:name.trim()})"/></label><label>角色大小 <span>{{ draftSize }} px</span><NSlider :value="draftSize" :min="80" :max="420" :step="10" @update:value="resizePet" @dragend="flushSize"/></label><label>显示层级<NSelect :value="current.layer" :options="layers" @update:value="layer=>update({layer})"/></label><label>心情<NSelect :value="current.expression" :options="expressions" @update:value="expression=>update({expression})"/></label><div class="pet-editor-toggle"><div><b>回应桌面状态</b><p>特效、问候和离开后的重逢。</p></div><NSwitch :value="current.links" @update:value="links=>update({links})"/></div><NButton block @click="update({x:.5,y:.5})">移到屏幕中间</NButton><NButton block @click="create(catalog.themes.find(t=>t.id===current!.themeId))"><template #icon><Sparkles :size="15"/></template>让 AI 换一株植物</NButton><NPopconfirm @positive-click="act(async()=>{await client.remove(current!.id);editing=null;})"><template #trigger><NButton block quaternary type="error" :disabled="busy">从桌面移除</NButton></template>移除这只宠物？主题作品仍会保留。</NPopconfirm></div></NDrawerContent></NDrawer>
</section>
</template>
<style scoped>
.pet-library{max-width:1420px;margin:0 auto;display:flex;flex-direction:column;gap:22px;color:var(--ui-text-primary)}.pet-library-header{display:flex;justify-content:space-between;gap:24px;align-items:center;margin-bottom:2px}.pet-eyebrow{font-size:12px;letter-spacing:2px;color:var(--ui-text-tertiary)}.pet-library-header h1{font-size:26px;letter-spacing:-1px;font-weight:650;margin:9px 0 8px}.pet-library-header p,.pet-section-heading p{font-size:12px;line-height:1.7;margin:0;color:var(--ui-text-secondary)}.pet-header-actions{display:flex;gap:10px;flex:none}.pet-theme-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.pet-theme-card{position:relative;min-width:0;padding:19px 20px 14px;border:1px solid var(--ui-border);border-radius:19px;background:linear-gradient(145deg,color-mix(in srgb,var(--theme-color) 16%,var(--ui-surface)),var(--ui-surface));text-align:left;font:inherit;color:inherit;cursor:pointer;overflow:hidden;transition:border-color .15s}.pet-theme-card.selected{border-color:var(--ui-primary);box-shadow:0 0 0 1px color-mix(in srgb,var(--ui-primary) 30%,transparent)}.theme-card-copy{display:flex;align-items:center;gap:9px}.theme-card-copy>svg{color:color-mix(in srgb,var(--theme-color) 70%,#51433f)}.theme-card-copy strong{font-size:15px;font-weight:650}.theme-card-copy small{margin-left:auto;font-size:10px;color:var(--ui-text-tertiary);white-space:nowrap}.theme-card-art{height:126px;display:flex;justify-content:center;align-items:center;margin:7px -8px}.theme-card-art img{width:38%;max-width:128px;height:auto;margin:0 -6px;filter:drop-shadow(0 2px 2px #604c3010)}.theme-card-art img:nth-child(2){transform:translateY(-4px) scale(1.06);z-index:1}.pet-theme-card>p{font-size:11px;color:var(--ui-text-secondary);margin:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.theme-selected{position:absolute;bottom:15px;right:14px;color:var(--ui-primary);background:var(--ui-surface);border-radius:50%}.pet-theme-detail{display:flex;flex-direction:column;gap:15px}.pet-section-heading{display:flex;justify-content:space-between;align-items:center;gap:20px}.pet-section-heading h2{display:flex;align-items:center;gap:10px;font-size:18px;margin:0 0 6px;font-weight:650}.pet-section-heading h2>span{font-size:11px;font-weight:400;color:var(--ui-text-tertiary);letter-spacing:0}.theme-actions{display:flex;align-items:center;gap:14px}.theme-actions button,.pet-manage{display:flex;align-items:center;gap:6px;border:0;background:none;font:inherit;font-size:12px;color:var(--ui-text-secondary);cursor:pointer;padding:6px}.theme-actions button:hover,.pet-manage:hover{color:var(--ui-primary)}.pet-add-preference{display:flex;align-items:center;justify-content:flex-end;gap:7px;font-size:11px;color:var(--ui-text-tertiary)}.pet-cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:16px}.pet-card{min-width:0;overflow:hidden;border-radius:19px;padding:12px 16px 16px}.pet-card-stage{height:198px;display:flex;justify-content:center;align-items:center;position:relative;background:radial-gradient(ellipse at 50% 65%,color-mix(in srgb,var(--theme-color) 17%,transparent),transparent 68%);margin:0 -8px 9px}.pet-card-stage img{display:block;flex:none}.pet-stage-hint{position:absolute;bottom:2px;font-size:10px;color:var(--ui-text-tertiary);opacity:0}.pet-card:hover .pet-stage-hint{opacity:1}.pet-card-copy h3{font-size:14px;font-weight:600;margin:0 0 7px}.pet-card-copy p{font-size:11px;line-height:1.7;min-height:37px;color:var(--ui-text-secondary);margin:0 0 14px}.desktop-pets{padding:23px;border-radius:19px}.all-pets-switch{display:flex;align-items:center;gap:10px;font-size:12px;color:var(--ui-text-secondary)}.desktop-pet-list{margin-top:15px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 24px}.desktop-pet-row{display:flex;align-items:center;gap:10px;min-width:0;padding:12px 0;border-top:1px solid var(--ui-border)}.desktop-pet-name{flex:1;min-width:0;display:grid;gap:5px}.desktop-pet-name strong{font-size:12px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.desktop-pet-name small{font-size:10px;color:var(--ui-text-tertiary);line-height:1.5}.pet-mood{font-size:10px;color:var(--ui-text-secondary);padding:4px 7px;border-radius:6px;background:var(--ui-surface-alt)}.pet-empty{padding:50px;text-align:center;border-radius:20px}.pet-empty>svg{color:var(--ui-primary);margin-bottom:14px}.pet-empty h2{font-size:18px;margin:0 0 12px}.pet-empty p,.desktop-pets-empty{font-size:12px;color:var(--ui-text-secondary);line-height:1.8;margin-bottom:18px}.desktop-pets-empty{padding-top:24px;margin:0}.pet-editor{display:grid;gap:22px}.pet-editor-stage{display:flex;justify-content:center;background:radial-gradient(ellipse,#f4e6d840,transparent 70%);padding:12px}.pet-editor>label{display:grid;gap:10px;font-size:12px}.pet-editor>label>span{font-size:11px;color:var(--ui-text-tertiary)}.pet-editor-toggle{display:flex;align-items:center;gap:15px;justify-content:space-between}.pet-editor-toggle b{font-size:12px;font-weight:500}.pet-editor-toggle p{font-size:11px;color:var(--ui-text-tertiary);margin:6px 0 0}@media(max-width:1100px){.pet-theme-grid{gap:10px}.pet-theme-card{padding:15px 12px}.theme-card-copy{gap:6px}.theme-card-copy small{display:none}.pet-library-header{align-items:flex-start;flex-direction:column;gap:16px}}@media(max-width:760px){.pet-theme-grid{grid-template-columns:1fr}.theme-card-art{height:100px}.theme-card-art img{max-width:110px}.desktop-pet-list{grid-template-columns:1fr}.pet-section-heading{align-items:flex-start;flex-wrap:wrap}.pet-library-header h1{font-size:23px}.pet-header-actions{flex-wrap:wrap}.pet-cards{grid-template-columns:repeat(2,minmax(0,1fr))}.pet-card{padding:8px 12px 12px}.pet-card-stage{height:170px;overflow:hidden}.pet-card-stage img{width:150px;height:150px}}
</style>
